func (this *Zaif) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// fetchTrades (public)
	//
	//      {
	//          "date": 1648559414,
	//          "price": 5880375.0,
	//          "amount": 0.017,
	//          "tid": 176126557,
	//          "currency_pair": "btc_jpy",
	//          "trade_type": "ask"
	//      }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var side *string = this.SafeString(trade, "trade_type")
	side = SafeStringPtr(func() string {
		if side != nil && *side == "bid" {
			return "buy"
		}
		return "sell"
	}())
	var timestamp *int64 = this.SafeTimestamp(trade, "date")
	var id *string = this.SafeString2(trade, "id", "tid")
	var priceString *string = this.SafeString(trade, "price")
	var amountString *string = this.SafeString(trade, "amount")
	var marketId *string = this.SafeString(trade, "currency_pair")
	var symbol *string = this.SafeSymbol(marketId, market, "_")
	return this.SafeTrade(map[string]any{
		"id":           id,
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"type":         nil,
		"side":         side,
		"order":        nil,
		"takerOrMaker": nil,
		"price":        priceString,
		"amount":       amountString,
		"cost":         nil,
		"fee":          nil,
	}, market)
}

