func (this *Zaif) fetchTradesBody(ch chan AsyncResult[[]Trade], symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair": market["id"],
	}

	listEp676 := <-this.PublicGetTradesPair(this.Extend(request, params))
	if listEp676.Err != nil {
		panic(listEp676.Err)
	}
	var response []any = listEp676.Value
	//
	//      [
	//          {
	//              "date": 1648559414,
	//              "price": 5880375.0,
	//              "amount": 0.017,
	//              "tid": 176126557,
	//              "currency_pair": "btc_jpy",
	//              "trade_type": "ask"
	//          }, ...
	//      ]
	//
	var trades []any = this.ToArray(response)
	var numTrades int = len(trades)
	if numTrades == 1 {
		var firstTrade map[string]any = SafeMapTyped(trades, 0)
		if len(firstTrade) == 0 {
			trades = []any{}
		}
	}

	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(trades, market, since, limit))}
	return nil
}

/**
 * @method
 * @name zaif#createOrder
 * @see https://zaif-api-document.readthedocs.io/ja/latest/MarginTradingAPI.html#id23
 * @description create a trade order
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type must be 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Zaif) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Zaif) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	if typeVar != "limit" {
		panic(ExchangeError(this.Id + " createOrder() allows limit orders only"))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"currency_pair": market["id"],
		"action": func() string {
			if side == "buy" {
				return "bid"
			}
			return "ask"
		}(),
		"amount": amount,
		"price":  price,
	}

	r1 := <-this.PrivatePostTrade(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	var data map[string]any = SafeMapTyped(response, "return")

	ch <- AsyncResult[Order]{Value: this.SafeOrder(map[string]any{
		"info": response,
		"id":   this.NumberToString(data["order_id"]),
	}, market)}
	return nil
}

