func (this *Zaif) ParseOrder(order any, optionalArgs ...any) Order {
	//
	//     {
	//         "currency_pair": "btc_jpy",
	//         "action": "ask",
	//         "amount": 0.03,
	//         "price": 56000,
	//         "timestamp": 1402021125,
	//         "comment" : "demo"
	//     }
	//
	// cancelOrder
	//
	//    {
	//        "order_id": 184,
	//        "funds": {
	//            "jpy": 15320,
	//            "btc": 1.392,
	//            "mona": 2600,
	//            "kaori": 0.1
	//        }
	//    }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var side *string = this.SafeString(order, "action")
	side = SafeStringPtr(func() string {
		if side != nil && *side == "bid" {
			return "buy"
		}
		return "sell"
	}())
	var timestamp *int64 = this.SafeTimestamp(order, "timestamp")
	var marketId *string = this.SafeString(order, "currency_pair")
	var symbol *string = this.SafeSymbol(marketId, market, "_")
	var price *string = this.SafeString(order, "price")
	var amount *string = this.SafeString(order, "amount")
	var id *string = this.SafeString2(order, "id", "order_id")
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      nil,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             "open",
		"symbol":             symbol,
		"type":               "limit",
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"cost":               nil,
		"amount":             amount,
		"filled":             nil,
		"remaining":          nil,
		"trades":             nil,
		"fee":                nil,
		"info":               order,
		"average":            nil,
	}, market)
}

