func (this *Zaif) withdrawBody(ch chan AsyncResult[Transaction], code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var tagWithdrawTag *string = nil
	tagWithdrawTag, paramsWithdrawTag := this.HandleParamString(params, "tag")
	this.CheckAddress(address, code, tagWithdrawTag)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	if code == "JPY" {
		panic(ExchangeError(this.Id + " withdraw() does not allow " + code + " withdrawals"))
	}
	var request map[string]any = map[string]any{
		"currency": currency["id"],
		"amount":   amount,
		"address":  address,
	}
	if tagWithdrawTag != nil {
		request["message"] = *tagWithdrawTag
	}

	r1 := <-this.PrivatePostWithdraw(this.Extend(request, paramsWithdrawTag))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var result map[string]any = r1.Value
	//
	//     {
	//         "success": 1,
	//         "return": {
	//             "id": 23634,
	//             "fee": 0.001,
	//             "txid":,
	//             "funds": {
	//                 "jpy": 15320,
	//                 "btc": 1.392,
	//                 "xem": 100.2,
	//                 "mona": 2600
	//             }
	//         }
	//     }
	//
	var returnData map[string]any = this.SafeDictMap(result, "return", map[string]any{})

	ch <- AsyncResult[Transaction]{Value: this.ParseTransaction(returnData, currency)}
	return nil
}
func (this *Zaif) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	//     {
	//         "id": 23634,
	//         "fee": 0.001,
	//         "txid":,
	//         "funds": {
	//             "jpy": 15320,
	//             "btc": 1.392,
	//             "xem": 100.2,
	//             "mona": 2600
	//         }
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var currencyResolved map[string]any = this.SafeCurrency(nil, currency)
	var fee map[string]any = nil
	var feeCost *float64 = this.SafeNumber(transaction, "fee")
	if feeCost != nil {
		fee = map[string]any{
			"cost":     feeCost,
			"currency": currencyResolved["code"],
		}
	}
	return TransactionFromMap(map[string]any{
		"id":          this.SafeString(transaction, "id"),
		"txid":        this.SafeString(transaction, "txid"),
		"timestamp":   nil,
		"datetime":    nil,
		"network":     nil,
		"addressFrom": nil,
		"address":     nil,
		"addressTo":   nil,
		"amount":      nil,
		"type":        nil,
		"currency":    currencyResolved["code"],
		"status":      nil,
		"updated":     nil,
		"tagFrom":     nil,
		"tag":         nil,
		"tagTo":       nil,
		"comment":     nil,
		"internal":    nil,
		"fee":         fee,
		"info":        transaction,
	})
}
func (this *Zaif) CustomNonce() any {
	var nonce float64 = float64(this.Milliseconds()) / 1000
	return ToFixed(nonce, 8)
}
func (this *Zaif) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiName string = api[0]
	var baseApiUrl *string = this.SafeString(this.Urls["api"], "rest")
	if baseApiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var baseUrl *string = baseApiUrl
	var url string = *baseUrl + "/"
	if apiName == "public" {
		url += "api/" + this.Version + "/" + this.ImplodeParams(path, params)
	} else if apiName == "fapi" {
		url += "fapi/" + this.Version + "/" + this.ImplodeParams(path, params)
	} else {
		this.CheckRequiredCredentials()
		if apiName == "ecapi" {
			url += "ecapi"
		} else if apiName == "tlapi" {
			url += "tlapi"
		} else {
			url += "tapi"
		}
		var nonce any = this.CustomNonce()
		var bodyEncoded string = this.Urlencode(this.Extend(map[string]any{
			"method": path,
			"nonce":  nonce,
		}, params))
		var headersSigned map[string]any = map[string]any{
			"Content-Type": "application/x-www-form-urlencoded",
			"Key":          this.ApiKey,
			"Sign":         this.Hmac(this.Encode(bodyEncoded), this.Encode(this.Secret), sha512),
		}
		return map[string]any{
			"url":     url,
			"method":  method,
			"body":    bodyEncoded,
			"headers": headersSigned,
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    nil,
		"headers": nil,
	}
}
func (this *Zaif) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil
	}
	//
	//     {"error": "unsupported currency_pair"}
	//
	var feedback string = this.Id + " " + body
	var error *string = this.SafeString(response, "error")
	if error != nil {
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], error, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], error, feedback)
		panic(ExchangeError(feedback))
	}
	var success *bool = this.SafeBool(response, "success", true)
	if !(success != nil && *success) {
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewZaif(userConfig map[string]any) *Zaif {
	p := newZaif()
	p.Init(userConfig)
	return p
}

func (this *Zaif) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

